#ifndef CSM_TEST_H
#define CSM_TEST_H

#include <stdio.h>
#include <string.h>

/* A minimal test framework: checks count, failures print and continue. */

extern int test_checks;
extern int test_failures;

#define CHECK(cond) \
	test_check((cond) != 0, #cond, __FILE__, __LINE__)
#define CHECK_STR(got, want) \
	test_check_str((got), (want), #got, __FILE__, __LINE__)

static inline void test_check(int ok, const char *text, const char *file,
    int line)
{
	test_checks++;
	if (ok)
		return;
	test_failures++;
	printf("%s:%d: failed: %s\n", file, line, text);
}

static inline void test_check_str(const char *got, const char *want,
    const char *text, const char *file, int line)
{
	test_checks++;
	if (got == NULL ? want == NULL : want != NULL && strcmp(got, want) == 0)
		return;
	test_failures++;
	printf("%s:%d: %s\n\tgot:  %s\n\twant: %s\n", file, line, text,
	    got != NULL ? got : "(null)", want != NULL ? want : "(null)");
}

#endif
